export default "\n    <!-- Main Wiki Application -->\n    <div id=\"wikiApp\" class=\"kr-app hidden\">\n        <!-- Topbar -->\n        <header class=\"kr-topbar\">\n            <div class=\"kr-brand\">\n                <button id=\"toggleSidebarBtn\" class=\"kr-icon-btn\" title=\"Toggle sidebar\" style=\"margin-right: 4px;\">\n                    <i class=\"bi bi-layout-text-window-reverse\"></i>\n                </button>\n                <!-- src/alt are swapped at runtime by /js/theme.js; sizing is in\n                     CSS (.kr-brand-logo) so a theme can restyle it. -->\n                <img id=\"brandLogo\" class=\"kr-brand-logo\" src=\"/wiki/images/noobly-logo-colour.png\" alt=\"noobly Wiki\">\n                <!-- Stands in for the logo while it is loading or while the\n                     space is still unknown. Setting img.src does not clear the\n                     picture already on screen, so without this the PREVIOUS\n                     space's mark stays in the header until the new file\n                     decodes. Shown/hidden purely by data-brand-loading /\n                     data-brand-pending on <html> (see /js/theme.js). -->\n                <span class=\"kr-brand-logo-skeleton\" aria-hidden=\"true\"></span>\n                <!-- Title/subtitle come from the current space's theme (see\n                     /js/theme.js). The text below is the unbranded default and\n                     is what a space with no theme reverts to, so keep the two\n                     elements even when a brand always overwrites them. -->\n                <div class=\"name\" id=\"brandName\"><span class=\"kr-brand-title\">noobly</span><small class=\"kr-brand-subtitle\">Wiki</small></div>\n            </div>\n            <div class=\"kr-search\">\n                <div class=\"wrap\">\n                    <input type=\"text\" id=\"globalSearch\" placeholder=\"Search files, spaces, capabilities, people…\"\n                           title=\"Tip: put quotes around words to match that exact phrase — &quot;Oracle MySQL&quot;\">\n                    <!-- Folder-scope chip: appears to the RIGHT of the query when you're\n                         inside a folder so search is limited to it. Styling lives in\n                         .kr-search-scope (kr-base.css). Click to clear and search the\n                         whole wiki. -->\n                    <button type=\"button\" id=\"searchScopeChip\" class=\"kr-search-scope hidden\" title=\"Searching within this folder. Click to clear and search the whole wiki.\">\n                        <i class=\"bi bi-folder2\"></i>\n                        <span id=\"searchScopeChipText\">in folder</span>\n                        <i class=\"bi bi-x\"></i>\n                    </button>\n                    <span class=\"kbd\">⌘K</span>\n                    <div id=\"searchSuggestions\" class=\"position-absolute top-100 start-0 w-100 bg-white border shadow-sm hidden\" style=\"z-index: 10;\">\n                        <!-- Search suggestions will be populated here -->\n                    </div>\n                </div>\n            </div>\n            <div class=\"kr-topbar-actions\">\n                <!-- Persona layout switcher (Detailed / Content / Chat / Search).\n                     Wired by layoutController; the active layout is stored in\n                     localStorage and chosen during onboarding. -->\n                <div class=\"kr-layout-switch\" id=\"layoutSwitch\" role=\"tablist\" aria-label=\"Choose your view\">\n                    <button type=\"button\" class=\"kr-layout-btn active\" data-layout=\"detailed\" role=\"tab\" aria-selected=\"true\" title=\"Detailed — full tree navigation\">\n                        <i class=\"bi bi-layout-sidebar\"></i><span>Detailed</span>\n                    </button>\n                    <button type=\"button\" class=\"kr-layout-btn\" data-layout=\"content\" role=\"tab\" aria-selected=\"false\" title=\"Content — browsing first\">\n                        <i class=\"bi bi-grid-1x2\"></i><span>Content</span>\n                    </button>\n                    <button type=\"button\" class=\"kr-layout-btn\" data-layout=\"chat\" role=\"tab\" aria-selected=\"false\" title=\"Chat — full-page assistant\">\n                        <i class=\"bi bi-chat-dots\"></i><span>Chat</span>\n                    </button>\n                    <button type=\"button\" class=\"kr-layout-btn\" data-layout=\"search\" role=\"tab\" aria-selected=\"false\" title=\"Search — start at the search bar\">\n                        <i class=\"bi bi-search\"></i><span>Search</span>\n                    </button>\n                </div>\n                <button id=\"helpToggleBtn\" class=\"kr-icon-btn\" title=\"Help\">\n                    <i class=\"bi bi-question-circle\"></i>\n                </button>\n                <button id=\"aiChatToggleBtn\" class=\"kr-icon-btn\" title=\"Toggle AI Assistant\">\n                    <i class=\"bi bi-robot\"></i>\n                </button>\n                <div id=\"notificationBellWrapper\" style=\"position: relative;\">\n                    <button id=\"notificationBellBtn\" class=\"kr-icon-btn\" title=\"Notifications\">\n                        <i class=\"bi bi-bell\"></i>\n                        <!-- Local class, NOT Bootstrap utilities: this app loads\n                             Bootstrap's JS but not its CSS, so the old\n                             `position-absolute … bg-danger d-none` markup was\n                             entirely inert — the count could never be hidden and\n                             rendered as bare text beside the bell. -->\n                        <span id=\"notificationBadge\" class=\"kr-bell-badge\" hidden>0</span>\n                    </button>\n                </div>\n                <div class=\"kr-avatar-pill\" id=\"userProfileBadge\">\n                    <span id=\"userName\">User</span>\n                    <div class=\"av\" id=\"userAvatar\">U</div>\n                </div>\n                <a href=\"#\" id=\"logoutBtn\" class=\"kr-icon-btn\" title=\"Logout\" style=\"margin-left: 4px;\">\n                    <i class=\"bi bi-box-arrow-right\"></i>\n                </a>\n            </div>\n        </header>\n\n        <!-- Headline banner — full-width announcement under the topbar. Hidden\n             (and its grid row collapsed) unless an admin has set a headline.\n             Backed by /wiki/api/v1/headline; driven by headlineController. -->\n        <div id=\"headlineBanner\" class=\"kr-headline hidden\" role=\"status\" aria-live=\"polite\">\n            <i class=\"bi bi-megaphone-fill\" aria-hidden=\"true\"></i>\n            <span data-headline-text></span>\n        </div>\n\n        <!-- Left Sidebar -->\n        <aside id=\"leftSidebar\" class=\"kr-sidebar\">\n            <div class=\"kr-side-section\">\n                <div class=\"kr-side-head\" id=\"shortcutsHeader\" data-bs-toggle=\"collapse\" data-bs-target=\"#shortcutsContent\" role=\"button\" style=\"cursor: pointer;\">\n                    <span>Shortcuts</span>\n                    <i class=\"bi bi-chevron-down\" style=\"font-size: 9px; color: var(--kr-ink-400);\"></i>\n                </div>\n                <div id=\"shortcutsContent\" class=\"collapse show\">\n                    <a href=\"#\" id=\"shortcutHome\" class=\"kr-nav-item\">\n                        <i class=\"bi bi-house-door\"></i> Home\n                    </a>\n                    <a href=\"#\" id=\"shortcutRecent\" class=\"kr-nav-item\">\n                        <i class=\"bi bi-clock-history\"></i> Recent\n                    </a>\n                    <a href=\"#\" id=\"shortcutStarred\" class=\"kr-nav-item\">\n                        <i class=\"bi bi-star\"></i> Starred\n                    </a>\n                    <a href=\"#\" id=\"shortcutTemplates\" class=\"kr-nav-item\">\n                        <i class=\"bi bi-journal-code\"></i> Templates\n                    </a>\n                </div>\n            </div>\n\n            <div class=\"kr-side-section\">\n                <div class=\"kr-side-head\">\n                    <span>Files</span>\n                    <div class=\"acts\">\n                        <button id=\"createFileBtn\" title=\"New File\"><i class=\"bi bi-file-earmark-plus\"></i></button>\n                        <button id=\"createFolderBtn\" title=\"New Folder\"><i class=\"bi bi-folder-plus\"></i></button>\n                        <button id=\"uploadBtn\" title=\"Upload File\"><i class=\"bi bi-upload\"></i></button>\n                    </div>\n                </div>\n                <div id=\"fileTree\" class=\"file-tree kr-tree\" style=\"min-height: 200px;\">\n                    <!-- Loading placeholder -->\n                    <div class=\"placeholder-glow\">\n                        <div class=\"placeholder col-10 mb-2\"></div>\n                        <div class=\"placeholder col-8 mb-2 ms-3\"></div>\n                        <div class=\"placeholder col-9 mb-2 ms-3\"></div>\n                        <div class=\"placeholder col-7 mb-2\"></div>\n                        <div class=\"placeholder col-11 mb-2 ms-3\"></div>\n                    </div>\n                </div>\n                <label class=\"kr-hide-empty\" title=\"Hide folders with no content (hidden files don't count)\">\n                    <input type=\"checkbox\" id=\"hideEmptyFoldersToggle\">\n                    <span>Hide empty folders</span>\n                </label>\n                <label class=\"kr-hide-empty\" title=\"Show a folder that holds only one subfolder as a single row (Parent &rsaquo; Child). Every part stays clickable.\">\n                    <input type=\"checkbox\" id=\"collapseChainsToggle\" checked>\n                    <span>Collapse single-folder chains</span>\n                </label>\n\n                <!-- In-page navigation for the open markdown document. Sits\n                     directly below the file tree (inside the Files section) and\n                     is hidden when no document is open. Populated by\n                     documentOutline.build(). -->\n                <div class=\"kr-outline-section\" id=\"docOutlineSection\" style=\"display: none;\">\n                    <div class=\"kr-side-head\">\n                        <span>On this page</span>\n                    </div>\n                    <nav id=\"docOutline\" class=\"kr-outline\" aria-label=\"Document outline\"></nav>\n                </div>\n            </div>\n\n            <div class=\"kr-side-section\">\n                <div class=\"kr-side-head\" id=\"spacesHeader\" data-bs-toggle=\"collapse\" data-bs-target=\"#spacesContent\" role=\"button\" style=\"cursor: pointer;\">\n                    <span>Spaces</span>\n                    <i class=\"bi bi-chevron-down\" style=\"font-size: 9px; color: var(--kr-ink-400);\"></i>\n                </div>\n                <div id=\"spacesContent\" class=\"collapse show\">\n                    <div id=\"spacesList\">\n                        <!-- Loading placeholder -->\n                        <div class=\"placeholder-glow\">\n                            <div class=\"d-flex align-items-center mb-2 p-2\">\n                                <div class=\"placeholder rounded-circle me-2\" style=\"width: 16px; height: 16px;\"></div>\n                                <div class=\"placeholder col-8\"></div>\n                            </div>\n                            <div class=\"d-flex align-items-center mb-2 p-2\">\n                                <div class=\"placeholder rounded-circle me-2\" style=\"width: 16px; height: 16px;\"></div>\n                                <div class=\"placeholder col-7\"></div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Resize Handle -->\n            <div id=\"sidebarResizeHandle\" class=\"sidebar-resize-handle kr-sidebar-resize\"></div>\n        </aside>\n\n        <!-- Chat-first layout: conversation history sidebar (only visible when\n             data-layout=\"chat\"). Populated by layoutController from localStorage. -->\n        <aside id=\"chatSessionsSidebar\" class=\"kr-chat-sidebar\">\n            <button type=\"button\" id=\"newChatBtn\" class=\"kr-newchat-btn\">\n                <i class=\"bi bi-plus-lg\"></i> New chat\n            </button>\n            <div class=\"kr-chat-recent-label\">Recent</div>\n            <div id=\"chatSessionsList\" class=\"kr-chat-sessions\"></div>\n        </aside>\n\n        <!-- Search-first layout: previous-searches sidebar (only visible when\n             data-layout=\"search\"). Populated by layoutController from localStorage. -->\n        <aside id=\"searchHistorySidebar\" class=\"kr-chat-sidebar kr-search-history\">\n            <div class=\"kr-chat-recent-label\">Previous searches</div>\n            <div id=\"searchHistoryList\" class=\"kr-chat-sessions\"></div>\n            <button type=\"button\" id=\"clearSearchHistoryBtn\" class=\"kr-clearhistory-btn\">\n                <i class=\"bi bi-trash\"></i> Clear history\n            </button>\n            <!-- Search-first layout: the faceted Filters panel is moved here from\n                 the results area (searchController renders into it when the\n                 layout is \"search\"); empty in every other layout. -->\n            <div id=\"searchFacetsSlot\" class=\"kr-search-facets-slot\"></div>\n        </aside>\n\n            <!-- Main Content Area -->\n        <main id=\"mainContent\" class=\"kr-main\">\n                <!-- Search-first layout: prominent search box at the top of the\n                     content area (only visible when data-layout=\"search\"). -->\n                <div id=\"layoutSearchPanel\">\n                    <div class=\"kr-search-hero\">\n                        <div class=\"kr-search-hero-box\">\n                            <i class=\"bi bi-search\"></i>\n                            <input type=\"text\" id=\"layoutSearchInput\" placeholder=\"Search files, spaces, capabilities, people…\" autocomplete=\"off\"\n                                   title=\"Tip: put quotes around words to match that exact phrase — &quot;Oracle MySQL&quot;\">\n                            <span class=\"kbd\">⌘K</span>\n                        </div>\n                        <div class=\"kr-search-hero-hint\">Type to search across every space, then press Enter to see all results.</div>\n                    </div>\n                </div>\n                <!-- Home View -->\n                <div id=\"homeView\" class=\"view\">\n                    <nav class=\"breadcrumb mb-3\">\n                        <a href=\"#\" id=\"homeBreadcrumbLink\" class=\"text-decoration-none\" style=\"color: var(--accent-link); font-weight: bold;\">Spaces</a>\n                        <span class=\"breadcrumb-separator\">/</span>\n                        <span class=\"last\" id=\"homeBreadcrumbLast\" style=\"color: var(--accent-link); font-weight: bold;\">Home</span>\n                    </nav>\n\n                    <div class=\"kr-page-hero\" style=\"display:none\">\n                        <div class=\"eyebrow\" id=\"homeHeroEyebrow\">Default Space</div>\n                        <h1 id=\"workspaceTitle\">Welcome to the Wiki</h1>\n                        <p id=\"workspaceSubtitle\">Your documentation workspace dashboard.</p>\n                        <div class=\"stats\" id=\"homeHeroStats\">\n                            <div class=\"stat\"><div class=\"k\" id=\"statDocs\">—</div><div class=\"l\">Documents</div></div>\n                            <div class=\"stat\"><div class=\"k\" id=\"statSpaces\">—</div><div class=\"l\">Active spaces</div></div>\n                            <div class=\"stat\"><div class=\"k\" id=\"statRecent\">—</div><div class=\"l\">Recently visited</div></div>\n                            <div class=\"stat\"><div class=\"k\" id=\"statStarred\">—</div><div class=\"l\">Starred</div></div>\n                        </div>\n                    </div>\n\n                    <!-- Home Content Area (for home.md)\n\n                         Deliberately NO notes chip here. A landing page has no\n                         action row for one to sit in, so it could only float in\n                         the top-right corner — where it lands on top of whatever\n                         the page opens with, which for a `landing-hero` is a\n                         full-bleed dark band it is unreadable against.\n                         Notes still target this page: app.js calls\n                         notesController.setTarget() when the home content loads,\n                         independently of any chip, so the panel opens on the\n                         right page from the document and folder chips or from\n                         wherever it was left open. -->\n                    <div id=\"homeContentArea\" class=\"kr-surface mb-3 hidden\">\n                        <div class=\"kr-surface-body markdown-content\" style=\"padding: 24px 28px;\">\n                            <div id=\"homeContentBody\">\n                                <!-- home.md content will be rendered here -->\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- User Dashboard (.dashboards/{email-prefix}.md) — read-only -->\n                    <section id=\"userDashboardSection\" class=\"kr-surface mb-3 hidden\">\n                        <div class=\"kr-surface-head\">\n                            <h3><i class=\"bi bi-speedometer2\"></i> My dashboard</h3>\n                        </div>\n                        <div class=\"kr-surface-body markdown-content\" style=\"padding: 24px 28px;\">\n                            <div id=\"userDashboardBody\">\n                                <!-- user's personal dashboard rendered by loadUserDashboard() -->\n                            </div>\n                        </div>\n                    </section>\n\n\n\n                    <!-- Home folder browse -->\n                    <section id=\"homeFolderSection\" class=\"kr-surface mb-3\">\n                        <div class=\"kr-surface-head\">\n                            <h3><i class=\"bi bi-folder2-open\"></i> <span id=\"homeFolderTitle\">Browse</span></h3>\n                            <div class=\"kr-seg view-mode-switcher\" data-target=\"homeFolder\">\n                                <button class=\"view-mode-btn active\" data-view=\"details\" title=\"List view\"><i class=\"bi bi-list-ul\"></i> List</button>\n                                <button class=\"view-mode-btn\" data-view=\"grid\" title=\"Grid view\"><i class=\"bi bi-grid-3x3-gap\"></i> Grid</button>\n                                <button class=\"view-mode-btn\" data-view=\"feature\" title=\"Feature view — cover image and headline\"><i class=\"bi bi-view-stacked\"></i> Feature</button>\n                                <button class=\"view-mode-btn\" data-view=\"cards\" title=\"Cards view\"><i class=\"bi bi-card-image\"></i> Cards</button>\n                            </div>\n                        </div>\n                        <div class=\"kr-surface-body\">\n                            <div id=\"homeFolderContent\">\n                                <!-- root folder list rendered by loadHomeFolder() -->\n                            </div>\n                        </div>\n                    </section>\n\n                    <!-- Pinned Documents and Folders -->\n                    <section class=\"kr-surface mb-3\">\n                        <div class=\"kr-surface-head\">\n                            <h3><i class=\"bi bi-pin-angle-fill\"></i> Pinned documents and folders</h3>\n                            <button id=\"refreshPinnedBtn\" class=\"kr-icon-btn\" style=\"color: var(--kr-ink-500); border: 1px solid var(--kr-border);\" title=\"Refresh\">\n                                <i class=\"bi bi-arrow-clockwise\"></i>\n                            </button>\n                        </div>\n                        <div class=\"kr-surface-body\">\n                            <div id=\"pinnedFilesContent\">\n                                <div class=\"kr-empty-tile\">\n                                    <div class=\"ico\"><i class=\"bi bi-pin-angle\"></i></div>\n                                    <h4>Nothing pinned yet</h4>\n                                    <p>Use the Pin button on a folder or document to anchor it here.</p>\n                                </div>\n                            </div>\n                        </div>\n                    </section>\n\n\n                    <!-- Recent Files (full width) -->\n                    <section class=\"kr-surface mb-3\">\n                        <div class=\"kr-surface-head\">\n                            <h3><i class=\"bi bi-clock-history\"></i> Recent files</h3>\n                            <div class=\"d-flex gap-2 align-items-center\">\n                                <span style=\"font-size:10px; color: var(--kr-ink-400)\">Sort: most recent</span>\n                                <div class=\"kr-seg view-mode-switcher\" data-target=\"recentHome\">\n                                    <button class=\"view-mode-btn active\" data-view=\"details\" title=\"List view\"><i class=\"bi bi-list-ul\"></i> List</button>\n                                    <button class=\"view-mode-btn\" data-view=\"grid\" title=\"Grid view\"><i class=\"bi bi-grid-3x3-gap\"></i> Grid</button>\n                                    <button class=\"view-mode-btn\" data-view=\"feature\" title=\"Feature view — cover image and headline\"><i class=\"bi bi-view-stacked\"></i> Feature</button>\n                                    <button class=\"view-mode-btn\" data-view=\"cards\" title=\"Cards view\"><i class=\"bi bi-card-image\"></i> Cards</button>\n                                </div>\n                                <button id=\"refreshRecentBtn\" class=\"kr-icon-btn\" style=\"color: var(--kr-ink-500); border: 1px solid var(--kr-border);\" title=\"Refresh\">\n                                    <i class=\"bi bi-arrow-clockwise\"></i>\n                                </button>\n                            </div>\n                        </div>\n                        <div class=\"kr-surface-body\">\n                            <div id=\"recentFilesContent\">\n                                <div class=\"kr-empty-tile\">\n                                    <div class=\"ico\"><i class=\"bi bi-clock-history\"></i></div>\n                                    <h4>No recent files yet</h4>\n                                    <p>Files you open will appear here for quick access.</p>\n                                </div>\n                            </div>\n                        </div>\n                    </section>\n\n                    <!-- Starred Files (full width) -->\n                    <section class=\"kr-surface\">\n                        <div class=\"kr-surface-head\">\n                            <h3><i class=\"bi bi-star-fill\"></i> Starred files</h3>\n                            <div class=\"kr-seg view-mode-switcher\" data-target=\"starredHome\">\n                                <button class=\"view-mode-btn active\" data-view=\"details\" title=\"List view\"><i class=\"bi bi-list-ul\"></i> List</button>\n                                <button class=\"view-mode-btn\" data-view=\"grid\" title=\"Grid view\"><i class=\"bi bi-grid-3x3-gap\"></i> Grid</button>\n                                <button class=\"view-mode-btn\" data-view=\"feature\" title=\"Feature view — cover image and headline\"><i class=\"bi bi-view-stacked\"></i> Feature</button>\n                                <button class=\"view-mode-btn\" data-view=\"cards\" title=\"Cards view\"><i class=\"bi bi-card-image\"></i> Cards</button>\n                            </div>\n                        </div>\n                        <div class=\"kr-surface-body\">\n                            <div id=\"starredFilesContent\">\n                                <div class=\"kr-empty-tile\">\n                                    <div class=\"ico\"><i class=\"bi bi-star\"></i></div>\n                                    <h4>No starred files yet</h4>\n                                    <p>Star documents to pin them here for quick access across your team.</p>\n                                </div>\n                            </div>\n                        </div>\n                    </section>\n                </div>\n\n                <!-- Spaces View -->\n                <div id=\"spacesView\" class=\"view hidden\">\n                    <nav class=\"kr-breadcrumb\">\n                        <a href=\"#\"><i class=\"bi bi-house-door\"></i></a>\n                        <span class=\"sep\">›</span>\n                        <span class=\"last\">Spaces</span>\n                    </nav>\n\n                    <div class=\"kr-page-hero\">\n                        <div class=\"eyebrow\">Workspaces</div>\n                        <h1>Available Spaces</h1>\n                        <p>Pick a workspace to browse its documents, capabilities, and architecture.</p>\n                    </div>\n\n                    <div id=\"spacesGrid\" class=\"kr-spaces-list\">\n                        <!-- Dynamic content -->\n                    </div>\n\n                    <!-- Quick Access: starred + recently-visited docs grouped by\n                         space (ported from the Teams wiki SpacesView). Populated\n                         by app.renderQuickAccess(); hidden when there's no activity. -->\n                    <div id=\"spacesQuickAccess\" class=\"kr-quick-access\" style=\"display:none;\">\n                        <!-- Dynamic content -->\n                    </div>\n                </div>\n\n                <!-- Space Detail View -->\n                <div id=\"spaceView\" class=\"view hidden\">\n                    <div class=\"space-header\">\n                        <nav class=\"breadcrumb\">\n                            <a href=\"#\" id=\"backToHome\">Home</a>\n                            <span class=\"breadcrumb-separator\">/</span>\n                            <span id=\"currentSpaceName\"></span>\n                        </nav>\n                        <div class=\"space-actions\">\n                            <button id=\"createDocInSpace\" class=\"btn btn-secondary\">+ New Document</button>\n                            <button id=\"createFolderInSpace\" class=\"btn btn-secondary\">+ New Folder</button>\n                        </div>\n                    </div>\n\n                    <div class=\"space-content-sections\">\n                        <!-- Recent Files in Space -->\n                        <section class=\"space-section\">\n                            <div class=\"section-header\">\n                                <div class=\"section-title\">\n                                    <svg width=\"20\" height=\"20\" class=\"section-icon\">\n                                        <use href=\"#icon-history\"></use>\n                                    </svg>\n                                    <h2>Recent Files</h2>\n                                </div>\n                            </div>\n                            <div id=\"spaceRecentFiles\" class=\"files-grid\">\n                                <!-- Recent files will be loaded here -->\n                            </div>\n                        </section>\n\n                        <!-- Starred Files in Space -->\n                        <section class=\"space-section\">\n                            <div class=\"section-header\">\n                                <div class=\"section-title\">\n                                    <svg width=\"20\" height=\"20\" class=\"section-icon\">\n                                        <use href=\"#icon-star\"></use>\n                                    </svg>\n                                    <h2>Starred Files</h2>\n                                </div>\n                            </div>\n                            <div id=\"spaceStarredFiles\" class=\"files-grid\">\n                                <!-- Starred files will be loaded here -->\n                            </div>\n                        </section>\n\n                        <!-- Root Files and Folders -->\n                        <section class=\"space-section\">\n                            <div class=\"section-header\">\n                                <div class=\"section-title\">\n                                    <svg width=\"20\" height=\"20\" class=\"section-icon\">\n                                        <use href=\"#icon-folder\"></use>\n                                    </svg>\n                                    <h2>Files & Folders</h2>\n                                </div>\n                            </div>\n                            <div id=\"spaceRootItems\" class=\"items-grid\">\n                                <!-- Root level files and folders will be loaded here -->\n                            </div>\n                        </section>\n                    </div>\n                </div>\n\n                <!-- Content is rendered directly into documentView below -->\n\n                <!-- Editor View -->\n                <div id=\"editorView\" class=\"view hidden\">\n                    <!-- Rendered by documentController.renderEditorBreadcrumb in the\n                         shared folder-view style (Spaces / space / folders / file). -->\n                    <nav class=\"breadcrumb\" id=\"editorBreadcrumb\"></nav>\n\n                    <div class=\"kr-doc-toolbar\">\n                        <div class=\"lhs\">\n                            <div class=\"doc-icon\" id=\"editorDocIcon\">md</div>\n                            <div>\n                                <h2 id=\"editorDocTitle\">Document</h2>\n                                <div class=\"meta\" id=\"editorDocMeta\"></div>\n                            </div>\n                        </div>\n                        <div class=\"rhs\">\n                            <span id=\"lastSavedIndicator\" class=\"text-muted small me-2\" style=\"display: none;\">\n                                <i class=\"bi bi-clock-history me-1\"></i>\n                                <span id=\"lastSavedTime\">Never saved</span>\n                            </span>\n                            <button id=\"saveDoc\" class=\"btn btn-primary btn-sm\">\n                                <i class=\"bi bi-check-lg\"></i> Save\n                            </button>\n                            <button id=\"closeEditor\" class=\"btn btn-ghost btn-sm\">\n                                <i class=\"bi bi-x-lg\"></i> Close\n                            </button>\n                            <div class=\"kr-seg editor-mode-toggle\" role=\"tablist\" aria-label=\"Editor mode\">\n                                <button type=\"button\" id=\"editorModeBlocks\" class=\"active\" data-mode=\"blocks\" aria-pressed=\"true\" title=\"Visual block editor\">\n                                    <i class=\"bi bi-grid-1x2\"></i> Blocks\n                                </button>\n                                <button type=\"button\" id=\"editorModeMarkdown\" data-mode=\"markdown\" aria-pressed=\"false\" title=\"Raw markdown — paste/edit text directly\">\n                                    <i class=\"bi bi-markdown\"></i> Markdown\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"editor-container\">\n                        <div class=\"editor-main\">\n                            <div id=\"markdownEditor\" class=\"editor-pane\">\n                                <!-- Markdown Block Editor will be initialized here -->\n                                <div id=\"editorTextarea\"></div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Document View -->\n                <div id=\"documentView\" class=\"view hidden\">\n                    <nav class=\"kr-breadcrumb\" id=\"docBreadcrumb\">\n                        <a href=\"#\" id=\"docBackToSpace\"><i class=\"bi bi-house-door\"></i> Space</a>\n                    </nav>\n\n                    <div class=\"kr-doc-toolbar\">\n                        <div class=\"lhs\">\n                            <div class=\"doc-icon\" id=\"docIcon\">md</div>\n                            <div>\n                                <h2 id=\"currentDocTitle\">Document</h2>\n                                <div class=\"meta\" id=\"docMeta\"></div>\n                            </div>\n                        </div>\n                        <div class=\"rhs\">\n                            <button id=\"pinDocBtn\" class=\"btn btn-ghost btn-sm pin-btn\">\n                                <i class=\"bi bi-pin-angle\"></i>\n                                <span class=\"pin-text\">Pin</span>\n                            </button>\n                            <button id=\"starDocBtn\" class=\"btn btn-ghost btn-sm star-btn\">\n                                <i class=\"bi bi-star\"></i>\n                                <span class=\"star-text\">Star</span>\n                            </button>\n                            <button id=\"subscribeDocBtn\" class=\"btn btn-ghost btn-sm\" title=\"Subscribe to changes\">\n                                <i class=\"bi bi-bell\"></i> Subscribe\n                            </button>\n                            <button id=\"requestReviewBtn\" class=\"btn btn-ghost btn-sm\" title=\"Request a review of this page from a colleague\">\n                                <i class=\"bi bi-clipboard-check\"></i> Request review\n                            </button>\n                            <button id=\"shareDocBtn\" class=\"btn btn-ghost btn-sm\" title=\"Copy a shareable link to this document\">\n                                <i class=\"bi bi-share\"></i> Share\n                            </button>\n                            <button id=\"downloadDocBtn\" class=\"btn btn-ghost btn-sm\">\n                                <i class=\"bi bi-download\"></i> Download\n                            </button>\n                            <button id=\"refreshDocBtn\" class=\"btn btn-ghost btn-sm\" title=\"Rebuild this content from source (runs the workflow declared in the document)\" style=\"display: none;\">\n                                <i class=\"bi bi-arrow-clockwise\"></i> Refresh\n                            </button>\n                            <button id=\"convertToMarkdownBtn\" class=\"btn btn-secondary btn-sm\" style=\"display: none;\">\n                                <i class=\"bi bi-file-earmark-text\"></i> Convert to Markdown\n                            </button>\n                            <button id=\"fullscreenDocBtn\" class=\"btn btn-ghost btn-sm\" title=\"View fullscreen\">\n                                <i class=\"bi bi-arrows-fullscreen\"></i>\n                            </button>\n                            <!-- Notes toggle. Every one of these across the app\n                                 carries data-notes-toggle and is driven by one\n                                 delegated handler in notesController — no ids,\n                                 so a view can render as many as it needs. -->\n                            <button type=\"button\" class=\"btn btn-ghost btn-sm kr-notes-chip\" data-notes-toggle\n                                    title=\"Your private notes about this page\">\n                                <i class=\"bi bi-journal-text\"></i> <span>Notes</span>\n                                <span class=\"kr-notes-count\" data-notes-count hidden>0</span>\n                            </button>\n                            <!-- Link documents. Carries no target of its own —\n                                 linkedDocumentsController infers the open\n                                 document, so the same markup works for every\n                                 markdown page the document view shows. -->\n                            <button type=\"button\" id=\"linkDocsBtn\" class=\"btn btn-ghost btn-sm\" data-link-documents\n                                    title=\"Link related documents and folders to this page\">\n                                <i class=\"bi bi-diagram-3\"></i> Link documents\n                            </button>\n                            <button id=\"editDocBtn\" class=\"btn btn-primary btn-sm\">\n                                <i class=\"bi bi-pencil\"></i> Edit\n                            </button>\n                        </div>\n                    </div>\n\n                    <!-- Content / editor tabs (markdown documents only). Switching\n                         tabs saves the active editor and keeps every view in sync.\n                         Replaces the old Edit + Visualise toolbar buttons. -->\n                    <div class=\"kr-doc-tabs\" id=\"docTabs\" role=\"tablist\" aria-label=\"Document views\" style=\"display: none;\">\n                        <button type=\"button\" class=\"kr-doc-tab active\" data-tab=\"content\" role=\"tab\" aria-selected=\"true\">\n                            <i class=\"bi bi-file-text\"></i> Content\n                        </button>\n                        <button type=\"button\" class=\"kr-doc-tab\" data-tab=\"blocks\" role=\"tab\" aria-selected=\"false\">\n                            <i class=\"bi bi-grid-1x2\"></i> Blocks\n                        </button>\n                        <button type=\"button\" class=\"kr-doc-tab\" data-tab=\"markdown\" role=\"tab\" aria-selected=\"false\">\n                            <i class=\"bi bi-markdown\"></i> Markdown\n                        </button>\n                        <button type=\"button\" class=\"kr-doc-tab\" data-tab=\"visualise\" role=\"tab\" aria-selected=\"false\">\n                            <i class=\"bi bi-diagram-3\"></i> Visualise\n                        </button>\n                        <button type=\"button\" class=\"kr-doc-tab\" data-tab=\"card\" role=\"tab\" aria-selected=\"false\">\n                            <i class=\"bi bi-card-image\"></i> Card\n                        </button>\n                        <!-- PDF documents only: the rendered PDF, and the derived\n                             markdown that feeds search/AI (editable, autosaving). -->\n                        <button type=\"button\" class=\"kr-doc-tab\" data-tab=\"pdf\" role=\"tab\" aria-selected=\"false\">\n                            <i class=\"bi bi-file-earmark-pdf\"></i> Document\n                        </button>\n                        <button type=\"button\" class=\"kr-doc-tab\" data-tab=\"derived\" role=\"tab\" aria-selected=\"false\">\n                            <i class=\"bi bi-markdown\"></i> Extracted text\n                        </button>\n                        <span class=\"kr-doc-tabs-status\" id=\"docTabsStatus\" aria-live=\"polite\"></span>\n                    </div>\n\n                    <div class=\"document-container kr-doc-paper\">\n                        <!-- Content will be inserted directly here by JavaScript -->\n                    </div>\n                </div>\n\n                <!-- Search Results View -->\n                <div id=\"searchView\" class=\"view hidden\">\n                    <div class=\"view-header\">\n                        <h1>Search Results</h1>\n                        <span id=\"searchQuery\" class=\"search-query\"></span>\n                    </div>\n                    <div id=\"searchResults\" class=\"search-results\">\n                        <!-- Dynamic content -->\n                    </div>\n                </div>\n\n                <!-- Profile View (rendered by profileController) -->\n                <div id=\"profileView\" class=\"view hidden\">\n                    <div id=\"profileContent\"></div>\n                </div>\n\n                <!-- Templates hub (rendered by templatesController): document\n                     templates (.templates/) + continuous exploration templates and\n                     continuous explorations (.continuous-explorations/) -->\n                <div id=\"templatesView\" class=\"view hidden\">\n                    <div id=\"templatesContent\"></div>\n                </div>\n\n                <!-- Continuous Exploration workspace (rendered by continuousExplorationController) -->\n                <div id=\"continuousExplorationView\" class=\"view hidden\">\n                    <div id=\"continuousExplorationContent\"></div>\n                </div>\n\n                <!-- Continuous Exploration creation wizard (rendered by continuousExplorationWizard) -->\n                <div id=\"continuousExplorationWizardView\" class=\"view hidden\">\n                    <div id=\"continuousExplorationWizardContent\"></div>\n                </div>\n\n                <!-- Deep Link Error View -->\n                <div id=\"deepLinkErrorView\" class=\"view hidden\">\n                    <div style=\"display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:60vh;padding:28px;text-align:center;\">\n                        <i class=\"bi bi-exclamation-triangle\" style=\"font-size:70px;color:#dc3545;margin-bottom:21px;\"></i>\n                        <h2 id=\"deepLinkErrorTitle\" style=\"font-size:22px;font-weight:600;margin-bottom:10.5px;\">Page Not Found</h2>\n                        <p id=\"deepLinkErrorDetail\" style=\"font-size:15px;color:#6c757d;max-width:480px;margin-bottom:28px;\">\n                            The page you requested could not be found.\n                        </p>\n                        <button class=\"btn btn-primary\" data-wk-action=\"home\">\n                            <i class=\"bi bi-house me-2\"></i>Go to Home\n                        </button>\n                    </div>\n                </div>\n            </main>\n\n        <!-- Notification Center Panel — sibling of #mainContent (NOT inside it),\n             so it still opens in the chat persona, which hides #mainContent. It's\n             position:fixed, so DOM location doesn't affect where it renders. -->\n        <div id=\"notificationPanel\" class=\"notification-panel hidden d-flex\" style=\"position: fixed; right: 0; top: 56px; width: 380px; max-width: 90vw; height: calc(100vh - 56px); background: var(--bs-body-bg); border-left: 1px solid var(--bs-border-color); z-index: 1000; overflow-y: auto; box-shadow: -2px 0 8px rgba(0,0,0,0.15); display: none;  flex-direction: column; \">\n            <!-- Panel Header with Close Button -->\n            <div class=\"notification-panel-header d-flex justify-content-between align-items-center p-3\" style=\"border-bottom: 1px solid var(--bs-border-color);\">\n                <h6 class=\"mb-0\">Updates</h6>\n                <button id=\"closeNotificationPanel\" class=\"btn btn-sm btn-close\"></button>\n            </div>\n\n            <!-- Tab Buttons -->\n            <div class=\"notification-tabs d-flex\" style=\"border-bottom: 1px solid var(--bs-border-color);\">\n                <button id=\"notificationsTab\" class=\"btn btn-link flex-fill rounded-0 active\" style=\"border: none; border-bottom: 2px solid var(--bs-primary); color: var(--bs-body-color); text-decoration: none;\">\n                    <i class=\"bi bi-bell me-1\"></i>Notifications\n                </button>\n                <button id=\"subscriptionsTab\" class=\"btn btn-link flex-fill rounded-0\" style=\"border: none; border-bottom: 2px solid transparent; color: var(--bs-secondary); text-decoration: none;\">\n                    <i class=\"bi bi-bookmark me-1\"></i>Subscriptions\n                </button>\n            </div>\n\n            <!-- List Container -->\n            <div id=\"notificationList\" class=\"notification-list p-2 flex-grow-1\" style=\"overflow-y: auto;\"></div>\n        </div>\n\n        <!-- AI Chat Panel (Right Sidebar) -->\n        <aside id=\"aiChatPanel\" class=\"ai-chat-panel kr-ai\">\n            <!-- Resize Handle -->\n            <div id=\"aiChatResizeHandle\" class=\"ai-chat-resize-handle\"></div>\n\n            <!-- AI Chat Header -->\n            <div class=\"kr-ai-head\">\n                <div class=\"title\">\n                    <div class=\"badge-pulse\"><i class=\"bi bi-stars\"></i></div>\n                    <div>\n                        <div class=\"t\" id=\"aiChatHeaderTitle\">AI Assistant</div>\n                        <div class=\"s\">Online · grounded on your space</div>\n                    </div>\n                </div>\n                <div class=\"acts\">\n                    <button id=\"aiContextViewToggleBtn\" title=\"Toggle Context View\"><i class=\"bi bi-folder-symlink\"></i></button>\n                    <button id=\"aiChatClearBtn\" title=\"Clear chat history\"><i class=\"bi bi-trash\"></i></button>\n                    <button id=\"aiChatCollapseBtn\" title=\"Close\"><i class=\"bi bi-x-lg\"></i></button>\n                </div>\n            </div>\n\n            <!-- Chat Body (messages / context view / context editor share this region) -->\n            <div class=\"kr-ai-body\">\n                <div id=\"aiChatMessages\" class=\"ai-chat-messages\">\n                    <!-- Welcome message -->\n                    <div class=\"ai-chat-welcome kr-ai-greet\">\n                        <div class=\"glyph\"><i class=\"bi bi-robot\"></i></div>\n                        <h4>Welcome to AI Assistant</h4>\n                        <p>Ask me anything about your wiki documents!</p>\n                        <small class=\"text-muted\">Configure AI settings to get started</small>\n                    </div>\n                </div>\n\n                <!-- Context View Area -->\n                <div id=\"aiContextView\" class=\"ai-context-view hidden\">\n                    <div class=\"ai-context-container\">\n                        <div class=\"ai-context-toolbar p-2 border-bottom\">\n                            <button class=\"btn btn-secondary btn-sm\" id=\"createContextBtn\">\n                                <i class=\"bi bi-plus-circle me-1\"></i>\n                                Create Context\n                            </button>\n                        </div>\n                        <div class=\"ai-context-list\" id=\"aiContextList\">\n                            <div class=\"text-center text-muted p-4\">\n                                <i class=\"bi bi-folder-symlink\" style=\"font-size: 42px;\"></i>\n                                <p class=\"mt-3 mb-1\"><strong>No context files found</strong></p>\n                                <p class=\"small\">Create context for folders to help AI understand your documents</p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Context Editor Area -->\n                <div id=\"aiContextEditor\" class=\"ai-context-editor hidden\">\n                    <div class=\"ai-context-editor-header p-2 border-bottom d-flex justify-content-between align-items-center\">\n                        <div>\n                            <button class=\"btn btn-ghost btn-sm\" id=\"contextEditorBackBtn\">\n                                <i class=\"bi bi-arrow-left me-1\"></i>\n                                Back\n                            </button>\n                            <span class=\"ms-2 text-muted\" id=\"contextEditorPath\"></span>\n                        </div>\n                        <!-- Icon-only: the panel is narrow and the folder path beside\n                             these can run to three lines, which squeezed labelled\n                             buttons off the edge. The name lives in title/aria-label. -->\n                        <div class=\"kr-ctx-actions\">\n                            <!-- Per-file regenerate. Hidden for the _folder.md\n                                 roll-up, which has no source document — that one\n                                 is rebuilt from the folder view's toolbar. -->\n                            <button class=\"btn btn-secondary btn-sm iconly hidden\" id=\"regenerateContextBtn\"\n                                    aria-label=\"Regenerate context\"\n                                    title=\"Regenerate this document's AI context. Runs in the background; the text below updates as it is written.\"><i class=\"bi bi-arrow-clockwise\"></i></button>\n                            <button class=\"btn btn-primary btn-sm iconly\" id=\"saveContextBtn\"\n                                    aria-label=\"Save context\" title=\"Save context\"><i class=\"bi bi-save\"></i></button>\n                        </div>\n                    </div>\n                    <!-- Live progress strip, shown only while a regeneration runs. -->\n                    <div class=\"kr-ctx-status hidden\" id=\"contextEditorStatus\" role=\"status\" aria-live=\"polite\"></div>\n                    <div class=\"ai-context-editor-body\">\n                        <!-- Height is owned by the stylesheet (~50 lines, shrinking\n                             to fit a short panel); an inline height would only\n                             re-introduce the percentage-of-auto-height dead end. -->\n                        <textarea id=\"contextEditorTextarea\" class=\"form-control border-0\" style=\"resize: none;\" placeholder=\"Enter context information for this folder...\n\nExamples:\n- Purpose of this folder\n- What files are stored here\n- Important conventions or standards\n- Related documentation\"></textarea>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Chat Input -->\n            <div class=\"kr-ai-foot\">\n                <!-- Quick prompts — only shown in the chat-first layout. -->\n                <div id=\"chatQuickPrompts\" class=\"kr-chat-quickprompts\">\n                    <button type=\"button\" data-prompt=\"Summarise this space\">Summarise this space</button>\n                    <button type=\"button\" data-prompt=\"What changed this week?\">What changed this week?</button>\n                    <button type=\"button\" data-prompt=\"Explain a diagram\">Explain a diagram</button>\n                </div>\n                <form id=\"aiChatForm\" class=\"ai-chat-form\">\n                    <div class=\"kr-ai-input\">\n                        <textarea id=\"aiChatInput\" placeholder=\"Ask anything…\" rows=\"1\" style=\"resize: none; max-height: 120px; flex: 1; border: 0; outline: 0; background: transparent; font-size: 11.5px; font-family: inherit;\"></textarea>\n                        <button type=\"submit\" class=\"send\" id=\"aiChatSendBtn\">\n                            <i class=\"bi bi-send-fill\"></i>\n                        </button>\n                    </div>\n                </form>\n                <!-- Scope toggle: ticked = only the current folder/page; unticked = whole wiki.\n                     Auto-ticks and relabels as you move between folders and pages. -->\n                <div class=\"ai-chat-scope\" id=\"aiChatScope\" style=\"display:none; align-items:center; padding:2px 10px 0;\">\n                    <label class=\"ai-chat-scope-label kr-hide-empty\" id=\"aiChatScopeLabel\" style=\"margin:0;\" title=\"When ticked, the assistant only looks within where you are. Untick to search the whole wiki.\">\n                        <input type=\"checkbox\" id=\"aiChatScopeToggle\" style=\"accent-color: var(--kr-teal-600, #02797d);\">\n                        <i class=\"bi bi-folder2\" id=\"aiChatScopeIcon\" style=\"font-size:11px;\"></i>\n                        <span id=\"aiChatScopeText\">Search the whole wiki</span>\n                    </label>\n                </div>\n                <div class=\"ai-chat-status text-muted small px-2 py-1\" id=\"aiChatStatus\">\n                    <span id=\"aiChatStatusText\"></span>\n                </div>\n            </div>\n        </aside>\n\n        <!-- Notes Panel (Right Sidebar) — private per-user notes about whatever\n             content is open (document, folder or space home). A grid child in\n             column 4, so opening it reflows the page rather than covering it;\n             it stays open across navigation until the Notes toggle is clicked\n             again. Driven by modules/notesController.js. -->\n        <aside id=\"notesPanel\" class=\"kr-notes-panel hidden\" aria-label=\"Notes\">\n            <div class=\"kr-notes-head\">\n                <div class=\"title\">\n                    <i class=\"bi bi-journal-text\"></i>\n                    <div>\n                        <div class=\"t\">Notes</div>\n                        <div class=\"s\" id=\"notesTargetLabel\">Private to you</div>\n                    </div>\n                </div>\n                <button id=\"notesCloseBtn\" class=\"kr-icon-btn\" title=\"Close notes\"><i class=\"bi bi-x-lg\"></i></button>\n            </div>\n\n            <div class=\"kr-notes-body\" id=\"notesBody\">\n                <div class=\"kr-notes-actions\">\n                    <button type=\"button\" class=\"kr-notes-new\" id=\"notesNewBtn\">\n                        <i class=\"bi bi-plus-lg\"></i> New note\n                    </button>\n                    <!-- Hidden until notesController confirms this browser can\n                         record. getUserMedia needs a SECURE CONTEXT, so over\n                         plain http (or in an iframe with no `microphone` in its\n                         allow list) navigator.mediaDevices is simply undefined\n                         — failing closed keeps a dead button off the panel. -->\n                    <button type=\"button\" class=\"kr-notes-new kr-notes-record\" id=\"notesRecordBtn\" hidden>\n                        <i class=\"bi bi-mic\"></i> Record\n                    </button>\n                </div>\n\n                <!-- Live recorder. Shown in place of the two buttons above\n                     while a recording is running. -->\n                <div class=\"kr-notes-recorder\" id=\"notesRecorder\" hidden>\n                    <span class=\"kr-rec-dot\" aria-hidden=\"true\"></span>\n                    <span class=\"kr-rec-time\" id=\"notesRecorderTime\" role=\"timer\" aria-live=\"off\">0:00</span>\n                    <div class=\"kr-rec-actions\">\n                        <button type=\"button\" class=\"btn btn-sm btn-primary\" id=\"notesRecorderStop\">\n                            <i class=\"bi bi-stop-fill\"></i> Stop\n                        </button>\n                        <button type=\"button\" class=\"btn btn-sm btn-ghost\" id=\"notesRecorderCancel\">Discard</button>\n                    </div>\n                </div>\n\n                <!-- \"Keep going?\" prompt, shown in place of the recorder every\n                     RECORD_PROMPT_MS. The recording is PAUSED behind this, and\n                     an unanswered prompt stops and SAVES rather than running\n                     on — so a microphone is never left live on nobody's behalf.\n                     `assertive` because it interrupts: a screen-reader user has\n                     a limited window to answer before it stops itself. -->\n                <div class=\"kr-notes-confirm\" id=\"notesRecorderConfirm\" hidden\n                     role=\"alertdialog\" aria-live=\"assertive\"\n                     aria-labelledby=\"notesRecorderConfirmLabel\">\n                    <div class=\"kr-rec-ask\" id=\"notesRecorderConfirmLabel\">\n                        <i class=\"bi bi-pause-circle-fill\" aria-hidden=\"true\"></i>\n                        Still recording? <b id=\"notesRecorderElapsed\">30:00</b> so far.\n                    </div>\n                    <div class=\"kr-rec-actions\">\n                        <button type=\"button\" class=\"btn btn-sm btn-primary\" id=\"notesRecorderContinue\">\n                            <i class=\"bi bi-record-fill\"></i> Continue\n                        </button>\n                        <button type=\"button\" class=\"btn btn-sm btn-secondary\" id=\"notesRecorderFinish\">\n                            Stop &amp; save\n                        </button>\n                        <span class=\"kr-rec-countdown\" id=\"notesRecorderCountdown\">Stopping in 60s</span>\n                    </div>\n                </div>\n\n                <div class=\"kr-notes-list\" id=\"notesList\"></div>\n            </div>\n\n            <div class=\"kr-notes-foot\">\n                <span id=\"notesFootStatus\">Autosaved</span>\n            </div>\n        </aside>\n\n        <!-- Picture viewer for the notes panel.\n             The figure inside is built fresh on every open and REMOVED on\n             close: it is a `.kr-image` canvas, which the markdown parser's own\n             pan/zoom runtime hydrates (ctrl/cmd+wheel zoom, drag to pan, and\n             the -/%/+/fit toolbar) — exactly the zoom a picture in a document\n             gets. That runtime measures the canvas to pick an opening zoom, so\n             the figure can only be inserted once this dialog is visible, and it\n             marks an image as hydrated, so a stale one would never re-fit.\n             Driven by modules/notesController.js. -->\n        <div class=\"kr-note-viewer\" id=\"noteImageViewer\" hidden\n             role=\"dialog\" aria-modal=\"true\" aria-label=\"Picture from a note\">\n            <div class=\"kr-note-viewer-panel\" id=\"noteImageViewerPanel\"></div>\n            <button type=\"button\" class=\"kr-note-viewer-close\" id=\"noteImageViewerClose\"\n                    aria-label=\"Close picture\"><i class=\"bi bi-x-lg\"></i></button>\n        </div>\n\n        <!-- Help & support drawer (opened from the topbar ? button) -->\n        <aside id=\"helpDrawer\" class=\"kr-help-drawer hidden\" aria-label=\"Help and support\">\n            <div class=\"kr-help-head\">\n                <div class=\"title\"><i class=\"bi bi-question-circle\"></i> Help &amp; support</div>\n                <button id=\"helpCloseBtn\" class=\"kr-icon-btn\" title=\"Close help\"><i class=\"bi bi-x-lg\"></i></button>\n            </div>\n            <div class=\"kr-help-search\">\n                <i class=\"bi bi-search\"></i>\n                <input id=\"helpSearchInput\" type=\"text\" placeholder=\"Search help…\" autocomplete=\"off\" spellcheck=\"false\">\n                <span class=\"kr-help-count\" id=\"helpSearchCount\"></span>\n                <button id=\"helpSearchPrev\" class=\"kr-help-nav-btn\" title=\"Previous match\"><i class=\"bi bi-chevron-up\"></i></button>\n                <button id=\"helpSearchNext\" class=\"kr-help-nav-btn\" title=\"Next match\"><i class=\"bi bi-chevron-down\"></i></button>\n            </div>\n            <div class=\"kr-help-thispage hidden\" id=\"helpThisPage\"><i class=\"bi bi-geo-alt\"></i> Help for this page</div>\n            <nav class=\"kr-help-nav\" id=\"helpNav\"></nav>\n            <div class=\"kr-help-body markdown-content\" id=\"helpBody\"></div>\n            <div class=\"kr-help-foot\" id=\"helpFoot\">\n                <a id=\"helpSupportBtn\" class=\"kr-help-support-btn\" href=\"#\" style=\"display:none;\"><i class=\"bi bi-life-preserver\"></i> Contact support</a>\n            </div>\n        </aside>\n\n        <!-- Source preview drawer — opened by clicking an AI chat source link.\n             Renders the linked document's markdown with the shared parser. -->\n        <aside id=\"docPreviewDrawer\" class=\"kr-doc-preview hidden\" aria-label=\"Document preview\">\n            <div class=\"kr-doc-preview-head\">\n                <div class=\"title\"><i class=\"bi bi-file-earmark-text\"></i> <span id=\"docPreviewTitle\">Document</span></div>\n                <div class=\"kr-doc-preview-actions\">\n                    <button id=\"docPreviewOpenBtn\" class=\"kr-doc-preview-open\" title=\"Open this document in Content view\"><i class=\"bi bi-box-arrow-up-right\"></i> Open</button>\n                    <button id=\"docPreviewCloseBtn\" class=\"kr-icon-btn\" title=\"Close preview\"><i class=\"bi bi-x-lg\"></i></button>\n                </div>\n            </div>\n            <div class=\"kr-doc-preview-sub\" id=\"docPreviewSub\"></div>\n            <div class=\"kr-doc-preview-body markdown-content\" id=\"docPreviewBody\"></div>\n        </aside>\n    </div>\n\n    <!-- Modals -->\n    <!-- Space Manager Modal\n         The five dialogs below are Bootstrap modals opened by app.showModal(),\n         not by Bootstrap's JS: `d-block` keeps them laid out and the wiki's\n         `.hidden` (display:none !important, loaded after Bootstrap) is what\n         hides them; #overlay is the matching .modal-backdrop. -->\n    <div id=\"spaceManagerModal\" class=\"modal d-block hidden\" tabindex=\"-1\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"spaceManagerModalTitle\">\n        <div class=\"modal-dialog modal-dialog-centered modal-dialog-scrollable\">\n            <div class=\"modal-content\">\n                <div class=\"modal-header\">\n                    <h5 class=\"modal-title\" id=\"spaceManagerModalTitle\">Manage Spaces</h5>\n                    <button type=\"button\" id=\"closeSpaceManagerModal\" class=\"btn-close\" aria-label=\"Close\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <p class=\"text-muted small mb-3\">Toggle which spaces appear in your sidebar.</p>\n                    <div id=\"spaceManagerList\" style=\"max-height: 400px; overflow-y: auto;\">\n                        <!-- Space items rendered dynamically -->\n                        <div class=\"text-center text-muted py-3\">Loading spaces...</div>\n                    </div>\n                </div>\n                <div class=\"modal-footer justify-content-between\">\n                    <button type=\"button\" id=\"spaceManagerCreateBtn\" class=\"btn btn-outline-secondary btn-sm\">\n                        <i class=\"bi bi-plus-lg me-1\"></i>Create New Space\n                    </button>\n                    <button type=\"button\" id=\"spaceManagerDoneBtn\" class=\"btn btn-primary btn-sm\">Done</button>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"createSpaceModal\" class=\"modal d-block hidden\" tabindex=\"-1\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"createSpaceModalTitle\">\n        <div class=\"modal-dialog modal-dialog-centered modal-dialog-scrollable\">\n            <div class=\"modal-content\">\n                <div class=\"modal-header\">\n                    <h5 class=\"modal-title\" id=\"createSpaceModalTitle\">Create New Space</h5>\n                    <button type=\"button\" id=\"closeCreateSpaceModal\" class=\"btn-close\" aria-label=\"Close\"></button>\n                </div>\n                <form id=\"createSpaceForm\">\n                    <div class=\"modal-body\">\n                        <div class=\"mb-3\">\n                            <label for=\"spaceName\" class=\"form-label\">Space Name</label>\n                            <input type=\"text\" class=\"form-control\" id=\"spaceName\" name=\"spaceName\" placeholder=\"My Space\" required>\n                        </div>\n                        <div class=\"mb-3\">\n                            <label for=\"spaceDescription\" class=\"form-label\">Description</label>\n                            <textarea class=\"form-control\" id=\"spaceDescription\" name=\"spaceDescription\" rows=\"2\" placeholder=\"Brief description of this space\"></textarea>\n                        </div>\n                        <div class=\"mb-3\">\n                            <label for=\"spaceVisibility\" class=\"form-label\">Visibility</label>\n                            <select class=\"form-select\" id=\"spaceVisibility\" name=\"spaceVisibility\">\n                                <option value=\"private\">Private</option>\n                                <option value=\"team\">Team</option>\n                                <option value=\"public\">Public</option>\n                            </select>\n                        </div>\n                        <div class=\"mb-3\">\n                            <label for=\"spaceType\" class=\"form-label\">Space Type</label>\n                            <select class=\"form-select\" id=\"spaceType\" name=\"spaceType\">\n                                <option value=\"personal\">Personal Space (Private, read-write)</option>\n                                <option value=\"shared\">Shared Space (Team, read-write)</option>\n                                <option value=\"readonly\">Read-Only Space (Reference materials)</option>\n                            </select>\n                            <div class=\"form-text\">Template determines folders and sample files to create</div>\n                        </div>\n                        <div class=\"mb-0\">\n                            <label for=\"spacePath\" class=\"form-label\">Folder Path</label>\n                            <div class=\"input-group\">\n                                <input type=\"text\" class=\"form-control\" id=\"spacePath\" name=\"spacePath\" placeholder=\"documents-my-space\" required>\n                                <button class=\"btn btn-outline-secondary\" type=\"button\" id=\"browseSpaceFolder\" title=\"Browse folder\">\n                                    <i class=\"bi bi-folder2-open\"></i>\n                                </button>\n                            </div>\n                            <div class=\"form-text\">Relative path from application root (e.g., documents-my-space)</div>\n                        </div>\n                    </div>\n                    <div class=\"modal-footer\">\n                        <button type=\"button\" id=\"cancelCreateSpace\" class=\"btn btn-secondary\">Cancel</button>\n                        <button type=\"submit\" class=\"btn btn-primary\">Create Space</button>\n                    </div>\n                </form>\n            </div>\n        </div>\n    </div>\n\n    <!-- Create Folder Modal -->\n    <div id=\"createFolderModal\" class=\"modal d-block hidden\" tabindex=\"-1\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"createFolderModalTitle\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n            <div class=\"modal-content\">\n                <div class=\"modal-header\">\n                    <h5 class=\"modal-title\" id=\"createFolderModalTitle\">Create New Folder</h5>\n                    <button type=\"button\" id=\"closeCreateFolderModal\" class=\"btn-close\" aria-label=\"Close\"></button>\n                </div>\n                <form id=\"createFolderForm\">\n                    <div class=\"modal-body\">\n                        <div class=\"mb-3\">\n                            <label for=\"folderName\" class=\"form-label\">Folder Name</label>\n                            <input type=\"text\" id=\"folderName\" name=\"folderName\" class=\"form-control\" required>\n                        </div>\n                        <div class=\"mb-0\" id=\"folderLocationInfo\" style=\"display: none;\">\n                            <span class=\"form-label\" style=\"margin: 0;\">Location: <span id=\"folderLocationText\" class=\"text-muted fw-normal\">Root</span></span>\n                        </div>\n                    </div>\n                    <div class=\"modal-footer\">\n                        <button type=\"button\" id=\"cancelCreateFolder\" class=\"btn btn-secondary\">Cancel</button>\n                        <button type=\"submit\" class=\"btn btn-primary\">Create Folder</button>\n                    </div>\n                </form>\n            </div>\n        </div>\n    </div>\n\n    <!-- Create File Modal -->\n    <div id=\"createFileModal\" class=\"modal d-block hidden\" tabindex=\"-1\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"createFileModalTitle\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n            <div class=\"modal-content\">\n                <div class=\"modal-header\">\n                    <h5 class=\"modal-title\" id=\"createFileModalTitle\">Create New File</h5>\n                    <button type=\"button\" id=\"closeCreateFileModal\" class=\"btn-close\" aria-label=\"Close\"></button>\n                </div>\n                <form id=\"createFileForm\">\n                    <div class=\"modal-body\">\n                        <div class=\"mb-3\">\n                            <label for=\"fileName\" class=\"form-label\">File Name</label>\n                            <input type=\"text\" id=\"fileName\" name=\"fileName\" class=\"form-control\" placeholder=\"MyDocument.md\" required>\n                        </div>\n                        <div class=\"mb-3\">\n                            <label for=\"fileLocation\" class=\"form-label\">Location</label>\n                            <select id=\"fileLocation\" name=\"fileLocation\" class=\"form-select\">\n                                <option value=\"\">Root</option>\n                                <!-- Dynamic options will be added here -->\n                            </select>\n                        </div>\n                        <div class=\"mb-0\" id=\"fileTemplatesGroup\">\n                            <div class=\"kr-tpl-chips\" id=\"fileTemplateChips\">\n                                <div class=\"kr-tpl-chips-empty\">No templates available for this space.</div>\n                            </div>\n                            <input type=\"hidden\" id=\"selectedTemplatePath\" name=\"selectedTemplatePath\" value=\"\">\n                        </div>\n                    </div>\n                    <div class=\"modal-footer\">\n                        <button type=\"button\" id=\"cancelCreateFile\" class=\"btn btn-secondary\">Cancel</button>\n                        <button type=\"submit\" class=\"btn btn-primary\">Create File</button>\n                    </div>\n                </form>\n            </div>\n        </div>\n    </div>\n\n    <!-- Rename Modal -->\n    <div id=\"renameModal\" class=\"modal d-block hidden\" tabindex=\"-1\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"renameModalTitle\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n            <div class=\"modal-content\">\n                <div class=\"modal-header\">\n                    <h5 class=\"modal-title\" id=\"renameModalTitle\">Rename <span id=\"renameItemType\">Item</span></h5>\n                    <button type=\"button\" id=\"closeRenameModal\" class=\"btn-close\" aria-label=\"Close\"></button>\n                </div>\n                <form id=\"renameForm\">\n                    <div class=\"modal-body\">\n                        <label for=\"newItemName\" class=\"form-label\">New Name</label>\n                        <input type=\"text\" id=\"newItemName\" name=\"newItemName\" class=\"form-control\" required>\n                    </div>\n                    <div class=\"modal-footer\">\n                        <button type=\"button\" id=\"cancelRename\" class=\"btn btn-secondary\">Cancel</button>\n                        <button type=\"submit\" class=\"btn btn-primary\">Rename</button>\n                    </div>\n                </form>\n            </div>\n        </div>\n    </div>\n\n    <!-- Context Menu for File Tree -->\n    <div id=\"fileContextMenu\" class=\"context-menu hidden\">\n        <div class=\"context-menu-item\" id=\"contextCreateFolder\">\n            <svg width=\"16\" height=\"16\">\n                <use href=\"#icon-folder\"></use>\n            </svg>\n            <span>Create Folder</span>\n        </div>\n        <div class=\"context-menu-item\" id=\"contextCreateFile\">\n            <svg width=\"16\" height=\"16\">\n                <use href=\"#icon-plus\"></use>\n            </svg>\n            <span>Create File</span>\n        </div>\n        <div class=\"context-menu-item\" id=\"contextUpload\">\n            <svg width=\"16\" height=\"16\">\n                <use href=\"#icon-share\"></use>\n            </svg>\n            <span>Upload File</span>\n        </div>\n        <div class=\"context-menu-separator\"></div>\n        <div class=\"context-menu-item\" id=\"contextCreateContinuousExploration\">\n            <i class=\"bi bi-flask me-2\"></i>\n            <span>Create Continuous Exploration</span>\n        </div>\n        <div class=\"context-menu-separator\"></div>\n        <div class=\"context-menu-item\" id=\"contextAddFileContext\">\n            <i class=\"bi bi-file-text me-2\"></i>\n            <span>Add Context</span>\n        </div>\n        <div class=\"context-menu-item context-menu-has-submenu\" id=\"contextSetFolderType\">\n            <i class=\"bi bi-palette me-2\"></i>\n            <span>Folder File Type</span>\n            <i class=\"bi bi-chevron-right context-submenu-caret\"></i>\n            <div class=\"context-submenu\" id=\"folderTypeSubmenu\">\n                <div class=\"context-menu-item folder-type-option\" data-status=\"default\">\n                    <span class=\"folder-type-swatch kr-ftype-default\"></span><span>Default</span>\n                </div>\n                <div class=\"context-menu-item folder-type-option\" data-status=\"success\">\n                    <span class=\"folder-type-swatch kr-ftype-success\"></span><span>Success</span>\n                </div>\n                <div class=\"context-menu-item folder-type-option\" data-status=\"danger\">\n                    <span class=\"folder-type-swatch kr-ftype-danger\"></span><span>Danger</span>\n                </div>\n                <div class=\"context-menu-item folder-type-option\" data-status=\"warning\">\n                    <span class=\"folder-type-swatch kr-ftype-warning\"></span><span>Warning</span>\n                </div>\n                <div class=\"context-menu-item folder-type-option\" data-status=\"light\">\n                    <span class=\"folder-type-swatch kr-ftype-light\"></span><span>Light</span>\n                </div>\n                <div class=\"context-menu-item folder-type-option\" data-status=\"continuous-exploration\">\n                    <span class=\"folder-type-swatch kr-ftype-continuous-exploration\"></span><span>Continuous Exploration</span>\n                </div>\n            </div>\n        </div>\n        <div class=\"context-menu-separator\"></div>\n        <div class=\"context-menu-item\" id=\"contextRename\">\n            <svg width=\"16\" height=\"16\">\n                <use href=\"#icon-edit\"></use>\n            </svg>\n            <span>Rename</span>\n        </div>\n        <div class=\"context-menu-item context-menu-item-danger\" id=\"contextDelete\">\n            <svg width=\"16\" height=\"16\">\n                <use href=\"#icon-x\"></use>\n            </svg>\n            <span>Delete</span>\n        </div>\n    </div>\n\n    <!-- Hidden file input for uploads -->\n    <input type=\"file\" id=\"fileUploadInput\" multiple style=\"display: none;\">\n\n    <div id=\"overlay\" class=\"modal-backdrop show hidden\"></div>\n\n    <!-- Sidebar and AI Panel Toggle Script -->\n    \n\n    <!-- Debug: Cache clearing utility for console -->\n    \n\n    <!-- External Scripts -->\n    \n    \n    \n    \n\n    <!-- Custom Markdown Parser (extends marked.js) -->\n    <!-- ?v bust: bump when markdown-parser.js changes so browsers fetch the new copy -->\n    \n\n    <!-- Application Scripts (?v bust: module files were renamed for Continuous Exploration) -->\n    \n";
